//! The macOS clipboard: NSPasteboard's general pasteboard, plain text only.
//!
//! `state` reads `changeCount` and `types`, never the contents, so it raises no pasteboard privacy
//! alert; `read_text` reads the text. Marks follow nspasteboard.org: `org.nspasteboard.ConcealedType`
//! is concealed, `org.nspasteboard.TransientType` and `org.nspasteboard.AutoGeneratedType` transient,
//! and a marked write adds the concealed or transient type, with empty data, before the text. The
//! pasteboard is fetched for every call inside an autorelease pool, on whichever thread calls, so
//! `Pasteboard` holds nothing and is `Send + Sync`. Every call here is safe in objc2-app-kit: no
//! `unsafe`.

use objc2::rc::{Retained, autoreleasepool};
use objc2_app_kit::NSPasteboard;
use objc2_foundation::{NSString, ns_string};

use super::{Clipboard, Marks, State, check_text};
use crate::{Error, ErrorCode};

/// How often `state` reads again when the count moved while it read the types.
const STATE_TRIES: usize = 3;

pub(super) struct Pasteboard;

/// The UTI of plain text, `NSPasteboardTypeString`'s value.
fn text_type() -> &'static NSString {
    ns_string!("public.utf8-plain-text")
}

fn concealed_type() -> &'static NSString {
    ns_string!("org.nspasteboard.ConcealedType")
}

fn transient_type() -> &'static NSString {
    ns_string!("org.nspasteboard.TransientType")
}

fn auto_generated_type() -> &'static NSString {
    ns_string!("org.nspasteboard.AutoGeneratedType")
}

fn general() -> Retained<NSPasteboard> {
    NSPasteboard::generalPasteboard()
}

/// The count as a `u64`; `changeCount` is never negative.
fn count(pasteboard: &NSPasteboard) -> u64 {
    pasteboard.changeCount() as u64
}

/// Whether there is text, and the marks, from the types on the pasteboard.
fn read_types(pasteboard: &NSPasteboard) -> (bool, Marks) {
    let (mut has_text, mut marks) = (false, Marks::default());
    if let Some(types) = pasteboard.types() {
        for kind in types.iter() {
            has_text |= kind.isEqualToString(text_type());
            marks.concealed |= kind.isEqualToString(concealed_type());
            marks.transient |= kind.isEqualToString(transient_type())
                || kind.isEqualToString(auto_generated_type());
        }
    }
    (has_text, marks)
}

impl Clipboard for Pasteboard {
    fn state(&self) -> Result<State, Error> {
        autoreleasepool(|_| {
            let pasteboard = general();
            let mut tries = 0;
            loop {
                let before = count(&pasteboard);
                let (has_text, marks) = read_types(&pasteboard);
                tries += 1;
                if count(&pasteboard) == before || tries == STATE_TRIES {
                    return Ok(State {
                        count: before,
                        has_text,
                        marks,
                    });
                }
            }
        })
    }

    fn read_text(&self) -> Result<Option<String>, Error> {
        autoreleasepool(|_| {
            let text = general().stringForType(text_type());
            Ok(text.map(|text| text.to_string()))
        })
    }

    fn write_text(&self, text: &str, marks: Marks) -> Result<(), Error> {
        check_text(text)?;
        autoreleasepool(|_| {
            let pasteboard = general();
            pasteboard.clearContents();
            // The marks go first, so an app that sees the text sees its marks too.
            let empty = ns_string!("");
            let written = (!marks.concealed
                || pasteboard.setString_forType(empty, concealed_type()))
                && (!marks.transient || pasteboard.setString_forType(empty, transient_type()))
                && pasteboard.setString_forType(&NSString::from_str(text), text_type());
            if written {
                return Ok(());
            }
            // Never leave text without the marks it was written with.
            pasteboard.clearContents();
            Err(Error::new(
                ErrorCode::IoError,
                "the pasteboard refused the text or a mark (setString:forType: answered NO)",
            ))
        })
    }
}
